<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;
require_once __DIR__.'/MariaDbPilotUserDirectory.php';

final class ProductionUserDirectoryRenderer
{
    public function renderUsers(HttpUser $actor,array $directory,array $tokens):string
    {
        $e=[PilotView::class,'e'];$users=$directory['users'];$roles=$directory['roles'];$active=\count(\array_filter($users,fn($x)=>$x['active']));$latest='';foreach([...$users,...$roles]as$item)$latest=\max($latest,$item['updatedAt']);$latestLabel=$latest===''?'Нет данных':(new \DateTimeImmutable($latest))->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');
        $inviteToken=$tokens[$actor->id]??'';$body='<div class="fm2-page-header"><div><h1>Пользователи</h1><p>Локальные учётные записи FMonitor и назначенные роли</p></div><span class="fm2-result-count">'.\count($users).' пользователей</span></div><section class="fm2-role-model-note"><strong>Преднастроить пользователя</strong><form method="post" action="/pilot/admin/users/invite" class="fm2-auth-form"><input type="hidden" name="csrfToken" value="'.$e($inviteToken).'"><input class="shlz-input" type="email" name="email" placeholder="name@shlz.ru" required><input class="shlz-input" name="fullName" placeholder="ФИО" required><button class="shlz-button shlz-button--primary" type="submit">Создать и выдать приглашение</button></form></section><section class="fm2-directory-summary fm2-user-summary"><div><strong>'.\count($users).'</strong><span>Всего</span></div><div><strong>'.$active.'</strong><span>Доступны</span></div><div><strong>'.(\count($users)-$active).'</strong><span>Заблокированы</span></div><p><b>Каталог FMonitor:</b> '.$e($latestLabel).'<br><span>Вход только по одноразовому приглашению</span></p></section>';
        $rows='';foreach($users as$user){$assigned=\array_column($user['roles'],'id');$tags='';foreach($user['roles']as$role)$tags.='<form class="shlz-tag fm2-role-chip" method="post" action="/pilot/admin/users/'.$user['id'].'/roles/'.$role['id'].'"><input type="hidden" name="csrfToken" value="'.$e($tokens[$user['id']]).'"><input type="hidden" name="action" value="detach"><span>'.$e($role['name']).'</span><button class="shlz-tag__remove" type="submit" aria-label="Снять роль '.$e($role['name']).' у '.$e($user['name']).'"><svg class="shlz-tag__icon" viewBox="0 0 12 12" aria-hidden="true"><path d="m3 3 6 6m0-6L3 9"/></svg></button></form>';if($tags==='')$tags='<span class="shlz-table__empty">Роли не назначены</span>';$options='';foreach($roles as$role)if($role['active']&&!\in_array($role['id'],$assigned,true))$options.='<option value="'.$role['id'].'">'.$e($role['name']).'</option>';$add=$options===''?'':'<form class="fm2-role-add" method="post" action="/pilot/admin/users/'.$user['id'].'/roles"><input type="hidden" name="csrfToken" value="'.$e($tokens[$user['id']]).'"><input type="hidden" name="action" value="attach"><select class="shlz-select" name="roleId" required aria-label="Добавить роль пользователю '.$e($user['name']).'"><option value="">Добавить роль</option>'.$options.'</select><button class="shlz-button shlz-button--secondary" type="submit">Назначить</button></form>';
            $rows.='<tr class="shlz-table__row fm2-user-row fm2-user-row--'.($user['active']?'active':'blocked').'" data-user-id="'.$user['id'].'" data-role-ids="'.\implode(',',\array_map('intval',$assigned)).'"><td class="shlz-table__cell" data-label="Пользователь"><span class="shlz-table__cell-content fm2-installer-person"><span class="shlz-avatar shlz-avatar--32" aria-hidden="true">'.PilotView::initials($user['name']).'</span><span><strong>'.$e($user['name']).'</strong><small>ID '.$user['id'].'</small></span></span></td><td class="shlz-table__cell" data-label="Контакты"><a class="shlz-link" href="mailto:'.$e($user['email']).'">'.$e($user['email']).'</a><small>'.$e($user['phone']!==''?$user['phone']:'Телефон не указан').'</small></td><td class="shlz-table__cell" data-label="Статус"><span class="fm2-employment fm2-employment--'.($user['active']?'active':'dismissed').'">'.($user['active']?'Активен':'Заблокирован').'</span></td><td class="shlz-table__cell" data-label="Роли"><div class="fm2-role-stack">'.$tags.$add.'</div></td></tr>';}
        $roleOptions='<button class="shlz-select__option" type="button" role="option" aria-selected="true" data-value="">Все роли</button>';foreach($roles as$role)$roleOptions.='<button class="shlz-select__option" type="button" role="option" aria-selected="false" data-value="'.$role['id'].'"><span>'.$e($role['name']).'</span><small>'.$role['userCount'].'</small></button>';
        $roleFilter='<div class="shlz-field shlz-field--select shlz-select-root fm2-role-filter" data-role-filter><span class="shlz-field__label" id="user-role-filter-label">Роль</span><button class="shlz-field__control shlz-select__trigger" type="button" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-controls="user-role-filter-options" aria-labelledby="user-role-filter-label user-role-filter-value"><span id="user-role-filter-value" data-role-filter-value>Все роли</span><svg class="shlz-select__chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8.5 12 15.5 19 8.5"/></svg></button><div class="shlz-select__listbox" id="user-role-filter-options" role="listbox" aria-labelledby="user-role-filter-label" hidden>'.$roleOptions.'</div><input type="hidden" value="" data-role-filter-input></div>';
        $body.='<section class="fm2-list-surface fm2-user-directory"><div class="fm2-user-toolbar"><label class="shlz-field"><span class="shlz-field__label">Поиск пользователей</span><span class="shlz-field__control fm2-search-control"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg><input class="shlz-input" type="search" placeholder="ФИО, email или телефон" autocomplete="off" data-user-search></span></label>'.$roleFilter.'<div class="fm2-installer-filters" aria-label="Фильтр пользователей"><input checked type="radio" name="user-filter" id="uf-all"><label for="uf-all">Все <b>'.\count($users).'</b></label><input type="radio" name="user-filter" id="uf-active"><label for="uf-active">Активные <b>'.$active.'</b></label><input type="radio" name="user-filter" id="uf-blocked"><label for="uf-blocked">Заблокированные <b>'.(\count($users)-$active).'</b></label></div></div><div class="shlz-table-wrap fm2-installer-table-scroll"><table class="shlz-table fm2-installer-table fm2-user-table"><thead class="shlz-table__head"><tr class="shlz-table__row"><th class="shlz-table__cell" scope="col">Пользователь</th><th class="shlz-table__cell" scope="col">Контакты</th><th class="shlz-table__cell" scope="col">Статус</th><th class="shlz-table__cell" scope="col">Роли</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section><script src="/pilot/assets/users.js" defer></script>';
        return PilotView::document($actor,'Пользователи','Пользователи','',$body);
    }

    public function renderRoles(HttpUser $actor,array $directory):string
    {
        $e=[PilotView::class,'e'];$roles=$directory['roles'];$assigned=\array_sum(\array_column($roles,'userCount'));$latest='';foreach($roles as$role)$latest=\max($latest,$role['updatedAt']);$latestLabel=$latest===''?'Нет данных':(new \DateTimeImmutable($latest))->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');$body='<div class="fm2-page-header"><div><h1>Роли</h1><p>Legacy-роли и унаследованные полномочия rapid pilot</p></div><span class="fm2-result-count">'.\count($roles).' ролей</span></div><section class="fm2-directory-summary fm2-role-summary"><div><strong>'.\count($roles).'</strong><span>Всего ролей</span></div><div><strong>'.\count(\array_filter($roles,fn($x)=>$x['active'])).'</strong><span>Активные</span></div><div><strong>'.$assigned.'</strong><span>Назначений</span></div><p><b>Снимок production:</b> '.$e($latestLabel).'<br><span>Права объединяются для всех назначенных ролей</span></p></section>';$labels=[AccessPolicy::OBJECTS_READ=>'Объекты',AccessPolicy::INSTALLERS_READ=>'Монтажники',AccessPolicy::CONSTRUCTION_CONTROL_READ=>'Стройконтроль',AccessPolicy::CHECKLIST_EDIT=>'Чек-лист',AccessPolicy::OTIZ_MANAGE=>'ОТиЗ',AccessPolicy::MANAGEMENT_READ=>'Контроль',AccessPolicy::ADMINISTER_ACCESS=>'Администрирование','assignment_order.prepare'=>'Распоряжение','assignment_order.confirm_registration'=>'Номер 1С ДО','installation.open'=>'Открытие работ','construction_control_engineer'=>'Инженер'];$rows='';foreach($roles as$role){$permissions='';foreach($role['permissions']as$permission)$permissions.='<span class="shlz-tag fm2-permission-chip">'.$e($labels[$permission]??$permission).'</span>';if($permissions==='')$permissions='<span class="shlz-table__empty">Интерактивных прав нет</span>';$rows.='<tr class="shlz-table__row"><td class="shlz-table__cell"><strong class="fm2-role-name">'.$e($role['name']).'</strong><small>ID '.$role['id'].'</small></td><td class="shlz-table__cell"><div class="fm2-permission-list">'.$permissions.'</div></td><td class="shlz-table__cell"><span class="fm2-employment fm2-employment--'.($role['active']?'active':'dismissed').'">'.($role['active']?'Активна':'Архивная').'</span></td><td class="shlz-table__cell shlz-table__cell--numeric"><strong>'.$role['userCount'].'</strong></td></tr>';}$body.='<section class="fm2-role-model-note"><strong>Как вычисляется доступ</strong><p>Роль импортируется из legacy FMonitor. Rapid pilot переводит стабильный ID роли в прикладные полномочия; персональные capabilities добавляются как исключения. Названия ролей не участвуют в проверке доступа.</p></section><section class="shlz-table-wrap fm2-list-surface fm2-role-surface"><table class="shlz-table fm2-role-table"><colgroup><col class="fm2-role-column"><col class="fm2-permissions-column"><col class="fm2-role-status-column"><col class="fm2-role-count-column"></colgroup><thead class="shlz-table__head"><tr class="shlz-table__row"><th class="shlz-table__cell" scope="col">Legacy-роль</th><th class="shlz-table__cell" scope="col">Полномочия rapid pilot</th><th class="shlz-table__cell" scope="col">Статус</th><th class="shlz-table__cell shlz-table__cell--numeric" scope="col">Пользователей</th></tr></thead><tbody>'.$rows.'</tbody></table></section>';return PilotView::document($actor,'Роли','Роли','',$body);
    }
}
